/* YK dashboard (adapted from the active baseball static interface): shared navigation, real league data, and linked exploration. */
(() => {
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n => Number(n || 0).toLocaleString('en-US', {maximumFractionDigits:1});
const date = value => value ? new Date(String(value).slice(0,10)+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) : 'Date unavailable';
const initials = name => (name || '?').split(/\s+/).map(x=>x[0]).slice(0,2).join('');
const normal = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const iconPaths = {
 overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
 teams:'<path d="M12 3l8 4v6c0 5-8 8-8 8s-8-3-8-8V7z"/><path d="M8 12l3 3 5-6"/>',
 players:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0112 0v3M16 5a3 3 0 010 6M18 15a5 5 0 013 4v2"/>',
 trades:'<path d="M4 7h16m-4-4l4 4-4 4M20 17H4m4-4l-4 4 4 4"/>',
 standings:'<path d="M5 20v-7h4v7M10 20V4h4v16M15 20V9h4v11M3 20h18"/>',
 drafts:'<path d="M8 4H5v17h14V4h-3M9 3h6v4H9zM8 12h8M8 16h5"/>',
 history:'<path d="M3 11a9 9 0 119 10M3 4v7h7M12 7v6l4 2"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="M16 16l5 5"/>',
 arrow:'<path d="M4 12h16m-5-5l5 5-5 5"/>',
 chevron:'<path d="M9 5l7 7-7 7"/>',
 close:'<path d="M6 6l12 12M18 6L6 18"/>',
 menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 trophy:'<path d="M7 3h10v6a5 5 0 01-10 0zM7 5H3v3a4 4 0 004 4M17 5h4v3a4 4 0 01-4 4M12 14v6M8 21h8"/>',
 ball:'<circle cx="12" cy="12" r="9"/><path d="M5 5c8 4 8 10 0 14M19 5c-8 4-8 10 0 14"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18"/>',
 compare:'<path d="M8 4v16M16 4v16M4 8h8M12 16h8M5 5L2 8l3 3M19 13l3 3-3 3"/>',
 check:'<path d="M4 12l5 5L20 6"/>',
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name] || iconPaths.ball}</svg>`;
let D={}, owners=[], ownerMap={}, playerMap={}, rosterMap={}, stintsByPlayer={}, view=document.body.dataset.page;
let year, currentYear, selectedOwner, page=1, sortKey='player_name', sortDirection=1, tableRows=[], pageSize=20, dialogTrigger;
const params=()=>new URLSearchParams(location.search);
const param=(key,fallback='')=>params().get(key) ?? fallback;
function setParams(values, push=false) {const p=params(); for(const [k,v] of Object.entries(values)) v === '' || v == null ? p.delete(k) : p.set(k,v); const url=location.pathname+(p.size?'?'+p:''); history[push?'pushState':'replaceState']({},'',url);}
function url(file, values={}) {const p=new URLSearchParams({season:String(year),...values});return `${file}?${p}`;}
const teamUrl=(name)=>url('team.html',{owner:name});
const playerUrl=(id)=>url('player.html',{id});
const operatorName=(name,season=year)=>ownerMap[name]?.operators_by_season?.[season] || name;
const teamName=(name,season=year)=>ownerMap[name]?.history.find(h=>h.season===String(season))?.team_name || ownerMap[name]?.real_name || name || 'Unresolved';
const colors=[['#deebfa','#234f82'],['#e9eff7','#3c5675'],['#dceafa','#285c96'],['#e6f2fa','#35657d'],['#e9edf5','#435f85'],['#dce6f5','#294d80'],['#e4eefb','#3264a3'],['#edf2f8','#536984'],['#dfedf7','#2b6187'],['#e6eaf4','#42577b']];
function badge(name,large=false) {const owner=ownerMap[name], c=colors[owner?.color_index || 0];const word=teamName(name);const letters=word.replace(/^(The |Gimmie )/,'').replace(/[’']/g,'').split(/[\s&]+/).filter(Boolean).slice(0,2).map(w=>w[0]).join('').toUpperCase();return `<span class="team-badge${large?' large':''}" style="--badge-bg:${c[0]};--badge-ink:${c[1]}" aria-hidden="true">${esc(letters)}</span>`;}
function teamCell(name,season=year) {return `<a class="team-cell" href="${url('team.html',{owner:name,season})}">${badge(name)}<span><strong>${esc(teamName(name,season))}</strong><small>${esc(operatorName(name,season))}</small></span></a>`;}
const playerLink=(id,name,avatar=true)=>`<a href="${playerUrl(id)}" class="player-button" title="Open ${esc(name)}’s player journey">${avatar?`<span class="player-avatar" aria-hidden="true">${esc(initials(name))}</span>`:''}<span>${esc(name)}</span></a>`;
const ownerOptions=(selected,all=false)=>`${all?'<option value="">All teams</option>':''}${owners.map(o=>`<option value="${esc(o.real_name)}" ${o.real_name===selected?'selected':''}>${esc(teamName(o.real_name))}</option>`).join('')}`;
const seasonRows=(season=year)=>D.standings.season_standings.filter(r=>r.season===String(season)).sort((a,b)=>a.rank-b.rank);
const ownerStanding=(owner,season=year)=>D.standings.season_standings.find(r=>r.owner_real_name===owner&&r.season===String(season));
const empty=(title,detail='Try a different search or clear your filters.')=>`<div class="empty"><h3>${esc(title)}</h3><p>${esc(detail)}</p></div>`;
const panel=(title,subtitle,body,action='',cls='')=>`<section class="panel ${cls}"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`;
const link=(label,href)=>`<a class="text-link" href="${href}">${label}${icon('arrow')}</a>`;
const metric=(label,value,note,ic='standings')=>`<div class="metric">${icon(ic)}<label>${label}</label><div class="value num">${value}</div><div class="metric-note">${note}</div></div>`;
function shell() {
 const nav=[['overview','Overview','index.html'],['teams','Teams','team.html'],['players','Players','player_history.html'],['trades','Trades','trade.html'],['standings','Standings','standings.html'],['drafts','Draft room','drafts.html'],['history','League history','history.html'],['rankings','Rankings','rankings.html'],['bubbles','Team bubbles','team_rankings.html']];
 const title=nav.find(n=>n[0]===view)?.[1] || ({roster:'Rosters',stats:'Player stats',reports:'Historical reports'})[view] || 'Player profile';
 $('#app').innerHTML=`<button class="backdrop-menu" aria-label="Close navigation" data-menu></button><aside class="sidebar"><a class="brand" href="${url('index.html')}"><img src="assets/yk-husky.png" alt="YK basketball crest"><span><strong>YK</strong><small>DYNASTY BASKETBALL</small></span></a><div class="nav-label">THE CLUBHOUSE</div><nav aria-label="Main navigation">${nav.map(([key,label,file])=>`<a class="side-link ${view===key || (view==='player'&&key==='players')?'active':''}" ${view===key?'aria-current="page"':''} href="${url(file)}">${icon(key)}${label}${view===key?`<span class="chevron">${icon('chevron')}</span>`:''}</a>`).join('')}</nav><div class="side-footer"><div class="league-note"><strong>One league. Every chapter.</strong>Every roster move has a story.<br>${owners.length} franchises · saved history</div><div class="team-picker"><button type="button" id="selected-team-button" class="sidebar-person" aria-expanded="false" aria-controls="selected-team-options" aria-label="Choose your team">${badge(selectedOwner)}<span><strong>${esc(teamName(selectedOwner))}</strong><small>Your team · Change ${icon('chevron').replace('class="icon"','class="icon" style="display:inline;width:10px;height:10px"')}</small></span></button><section id="selected-team-options" class="team-picker-options" aria-label="Choose your team" hidden><div class="team-picker-title">YOUR SELECTED TEAM</div>${owners.map(o=>`<button type="button" class="team-picker-option" data-select-owner="${esc(o.real_name)}" aria-pressed="${o.real_name===selectedOwner}">${badge(o.real_name)}<span><strong>${esc(teamName(o.real_name))}</strong><small>${esc(operatorName(o.real_name))}</small></span>${o.real_name===selectedOwner?icon('check'):''}</button>`).join('')}</section></div></div></aside><div class="main-wrap"><header class="topbar"><button class="mobile-menu" aria-label="Open navigation" aria-expanded="false" data-menu>${icon('menu')}</button><div class="breadcrumb">The clubhouse <span aria-hidden="true"> / </span> <b>${title}</b></div><div class="top-search"><div class="search-field">${icon('search')}<input id="global-search" type="search" aria-label="Search players and teams" placeholder="Search players, teams…" autocomplete="off" aria-controls="global-results" aria-expanded="false"><span class="key-hint">/</span></div><div id="global-results" class="search-results" hidden></div></div><span class="updated"><span class="fresh-dot"></span>${year===D.default_season?'Roster refreshed':'Saved archive'}</span><label class="season-control"><span>Season</span><select id="season-select" aria-label="Season">${D.teams.meta.seasons.slice().reverse().map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label></header><main id="main-content" class="page" tabindex="-1"></main></div>`;
 $('#selected-team-button').addEventListener('click',toggleTeamPicker);
 $('#season-select').addEventListener('change',e=>{setParams({season:e.target.value,page:null},true);activateSeason(e.target.value);page=1;shell();render();$('#season-select').focus();});
 $('#global-search').addEventListener('input',globalSearch);
 $('#global-search').addEventListener('keydown',e=>{if(e.key==='ArrowDown'){e.preventDefault();$('#global-results a')?.focus();}if(e.key==='Escape')closeSearch();if(e.key==='Enter'){$('#global-results a')?.click();}});
 syncMenuAccessibility();
}
function syncMenuAccessibility(){const mobile=matchMedia('(max-width:700px)').matches,open=document.body.classList.contains('menu-open');if($('.sidebar'))$('.sidebar').inert=mobile&&!open;if($('.main-wrap'))$('.main-wrap').inert=mobile&&open;}
function closeTeamPicker(restoreFocus=false) {
 const options=$('#selected-team-options');
 if(!options || options.hidden)return;
 options.hidden=true;
 $('#selected-team-button').setAttribute('aria-expanded','false');
 if(restoreFocus)$('#selected-team-button').focus();
}
function toggleTeamPicker() {
 const options=$('#selected-team-options');
 const opening=options.hidden;
 options.hidden=!opening;
 $('#selected-team-button').setAttribute('aria-expanded',String(opening));
 if(opening)options.querySelector('[aria-pressed="true"]')?.focus();
}
function selectTeam(owner) {
 if(!ownerMap[owner])return;
 selectedOwner=owner;
 try{localStorage.setItem('yk_selected_owner',owner);}catch{}
 // A preference change updates this clubhouse, but ordinary team browsing does not change the preference.
 if(view==='teams'){
  page=1;
  setParams({owner,q:null,filterOwner:null,status:null,position:null,page:null,compare:null});
 }
 document.body.classList.remove('menu-open');
 shell();render();
 $('#selected-team-button').focus();
 if(matchMedia('(max-width:700px)').matches)$('#main-content').focus();
}
function shellNavUpdate(){document.querySelectorAll('.side-link,.brand').forEach(a=>{const u=new URL(a.href);u.searchParams.set('season',year);a.href=u.pathname+u.search;});}
function globalSearch(e){const q=normal(e.target.value).trim(), box=$('#global-results');if(q.length<2){closeSearch();return;}const ts=owners.filter(o=>normal(teamName(o.real_name)+' '+o.real_name+' '+o.history.map(h=>h.team_name).join(' ')).includes(q)).slice(0,4);const ps=Object.entries(playerMap).filter(([,p])=>normal(p.player_name).includes(q)).slice(0,7);box.innerHTML=`${ts.length?'<div class="search-group">TEAMS</div>'+ts.map(o=>`<a class="search-result" href="${teamUrl(o.real_name)}">${badge(o.real_name)}<span><strong>${esc(teamName(o.real_name))}</strong><small>${esc(operatorName(o.real_name))}</small></span></a>`).join(''):''}${ps.length?'<div class="search-group">PLAYERS</div>'+ps.map(([id,p])=>`<a class="search-result" href="${playerUrl(id)}"><span class="player-avatar">${esc(initials(p.player_name))}</span><span><strong>${esc(p.player_name)}</strong><small>${esc(rosterMap[id]?.team_name || 'Not in this saved roster')} · ${esc(rosterMap[id]?.position || 'League history')}</small></span></a>`).join(''):''}${!ts.length&&!ps.length?empty('No matches'):''}`;box.hidden=false;e.target.setAttribute('aria-expanded','true');}
function closeSearch(){const results=$('#global-results');if(results)results.hidden=true;$('#global-search')?.setAttribute('aria-expanded','false');}
function heading(title,subtitle,action='',eyebrow='YK DYNASTY'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
// Basketball-specific views consume the normalized bundle below the retained shell.
function activateSeason(requested) {
 const selected=YKNormalize.select(D,requested);year=selected.season;D.rosters=selected.roster;
 rosterMap=Object.fromEntries(D.rosters.players.map(p=>[p.player_id,p]));
}
const previousSeason=()=>YKNormalize.previous(year);
const rosterAvailable=()=>D.rosters.meta.total_rostered!==null;
const seasonLabel=s=>String(s).replace('-', '–');
const record=s=>s?`${s.w ?? '—'}–${s.l ?? '—'}${s.t?'–'+s.t:''}`:'—';
const value=n=>n==null?'—':fmt(n);
function footer(){const contextView=view==='drafts'||(view==='trades'&&param('tradeView')==='updates');return `<footer class="footer"><span class="brand-mini"><img src="assets/yk-husky.png" alt=""><span>YK DYNASTY</span></span><span>${contextView?'Supplied workbook records · imported '+esc(D.context.imported_at)+' · outcomes may be unresolved':esc(seasonLabel(year))+' roster · '+(D.rosters.meta.as_of?'captured '+date(D.rosters.meta.as_of):'capture date unavailable')+' · partial history'}</span></footer>`;}
function coverageNote(){return `<div class="notice" role="note"><strong>${esc(seasonLabel(year))} roster.</strong> ${D.rosters.meta.as_of?'Captured '+date(D.rosters.meta.as_of)+'.':'Original capture date unavailable.'} ${year===D.default_season?'Current standings, weekly results and NBA production have not been collected; no older performance is substituted.':year==='2025-26'?'Standings and NBA stats are partial.':'Historical snapshot.'} <a class="text-link" href="${url('history.html',{tab:'coverage'})}">Coverage & verification</a></div>`;}
function change(owner){const a=ownerStanding(owner),b=ownerStanding(owner,previousSeason());if(!a||!b)return '<span class="change">—</span>';const delta=b.rank-a.rank;return `<span class="change ${delta>0?'up':delta<0?'down':''}" title="Recorded rank change from ${previousSeason()}">${delta>0?'↑':delta<0?'↓':'–'} ${delta?Math.abs(delta):'Even'}</span>`;}
function standingsTable(rows=seasonRows(),compact=false){const max=Math.max(...rows.map(r=>r.pts||0),1);return rows.length?`<div class="table-wrap"><table><thead><tr><th scope="col">#</th><th scope="col">Team</th><th scope="col">W–L–T</th><th scope="col">Fantasy points</th>${compact?'':'<th scope="col">Win %</th><th scope="col">Points against</th><th scope="col">vs. previous season</th>'}</tr></thead><tbody>${rows.map(r=>`<tr class="${r.owner_real_name===selectedOwner?'selected':''}"><td class="rank ${r.rank===1?'first':''}">${String(r.rank).padStart(2,'0')}</td><td>${teamCell(r.owner_real_name,r.season)}</td><td>${record(r)}</td><td class="points">${value(r.pts)}<div class="point-meter"><span style="width:${(r.pts||0)/max*100}%"></span></div></td>${compact?'':`<td>${r.win_pct==null?'—':(100*r.win_pct).toFixed(1)+'%'}</td><td>${value(r.points_against)}</td><td>${change(r.owner_real_name)}</td>`}</tr>`).join('')}</tbody></table></div>`:empty('Standings unavailable','No saved standings for this season.');}
function tradeActor(t,franchise){return [...new Set(t.assets.filter(a=>a.sender===franchise).map(a=>a.recorded_operator).filter(Boolean))].join(' / ')||franchise;}
function tradeFeed(events,limit=4){return events.length?events.slice(0,limit).map(t=>`<a class="activity-item" style="display:block" href="${url('trade.html',{trade:t.event_id})}" data-trade="${esc(t.event_id)}"><div class="activity-top"><span class="pill">${esc(t.trade_type_label)}</span><time>${t.date_iso?date(t.date_iso):esc(seasonLabel(t.year))+' · date unknown'}</time></div><p>${t.parties.map(p=>esc(tradeActor(t,p).split(' ').slice(-1)[0])).join(' <span class="muted">↔</span> ')||'Unresolved parties'}</p><div class="activity-detail">${esc(t.assets.slice(0,3).map(a=>a.label).join(' · '))}</div></a>`).join(''):empty('No recorded trades','The archive is incomplete; an empty list does not prove there were no trades.');}
function sortedTrades(){return D.trades.trade_events.slice().sort((a,b)=>b.year.localeCompare(a.year)||(b.date_iso||'').localeCompare(a.date_iso||'')||b.source_index-a.source_index);}
function trendChart(names,small=false){const years=D.teams.meta.seasons.filter(s=>seasonRows(s).length),width=560,height=small?150:220,left=28,right=22,top=20,bottom=30,max=owners.length;
 if(!years.length)return empty('No recorded standings');
 const x=i=>left+i/Math.max(years.length-1,1)*(width-left-right),y=r=>top+(r-1)/Math.max(max-1,1)*(height-top-bottom);
 return `<div class="panel-body"><svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Recorded standings ranks, first at the top">${[1,Math.ceil(max/2),max].map(r=>`<line class="axis" x1="${left}" x2="${width-right}" y1="${y(r)}" y2="${y(r)}"/><text x="3" y="${y(r)+4}">${r}</text>`).join('')}${years.map((s,i)=>`<text x="${x(i)}" y="${height-6}" text-anchor="middle">${s.slice(2)}</text>`).join('')}${names.map((n,i)=>{let path='',started=false;years.forEach((s,j)=>{const r=ownerStanding(n,s);if(!r){started=false;return;}path+=`${started?'L':'M'}${x(j)},${y(r.rank)} `;started=true;});return `<path class="trend ${i?'gold-trend':''}" d="${path}"/>${years.map((s,j)=>{const r=ownerStanding(n,s);return r?`<circle class="dot ${i?'gold-dot':''}" cx="${x(j)}" cy="${y(r.rank)}" r="4"><title>${esc(n)} · ${s} · #${r.rank}</title></circle>`:'';}).join('')}`;}).join('')}</svg><div class="legend">${names.map((n,i)=>`<span><i class="${i?'gold':''}"></i>${esc(teamName(n))}</span>`).join('')}</div><p class="status-line">Recorded standings, not playoff finishes. 2025–26 is a partial snapshot.</p><details class="chart-detail"><summary>View rank data</summary><div class="table-wrap"><table><thead><tr><th>Team</th>${years.map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${names.map(n=>`<tr><td>${esc(n)}</td>${years.map(s=>`<td>${ownerStanding(n,s)?.rank??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></div>`;
}
function rosterBreakdown(owner){const rows=D.rosters.by_owner[owner]||[];return `<div class="panel-body"><div class="bar-chart">${['ACTIVE','RESERVE','IR','MINORS'].map(s=>{const n=rows.filter(p=>p.roster_status===s).length;return `<div class="bar-line"><span>${esc(s)}</span><div class="bar-track"><div class="bar-fill" style="width:${n/Math.max(rows.length,1)*100}%"></div></div><strong>${n}</strong></div>`;}).join('')}</div><p class="status-line">Saved roster status. Acquisition methods and start dates are unknown.</p></div>`;}
function overview(){const rows=seasonRows(),s=ownerStanding(selectedOwner),trades=sortedTrades().filter(t=>t.year===year),champ=D.standings.champions[year];return `${heading('League overview',`Your ${seasonLabel(year)} season, in focus.`,`<a class="btn" href="${teamUrl(selectedOwner)}">${icon('teams')}Open my team${icon('arrow')}</a>`)}${coverageNote()}<section class="hero"><div><div class="eyebrow">THE CLUBHOUSE · YK DYNASTY</div><h2>Every season has a story.</h2><p>Follow the rosters. Revisit the deals. Know your league.</p><div class="hero-footer"><span>${owners.length} FRANCHISES</span><span>${Object.keys(D.rosters_by_season).length} SAVED ROSTER SEASONS</span><span>${D.trades.trade_events.length} RECORDED TRADES</span></div></div></section><div class="context-strip"><span><strong>Rankings, from every angle</strong><small>Dynasty & current season · individual sources · roster coverage</small></span><div class="buttons">${link('Explore players',url('rankings.html'))}${link('Team bubbles',url('team_rankings.html'))}</div></div><div class="metric-row">${metric('Your standing',s?'#'+s.rank:'—',`${esc(teamName(selectedOwner))} · ${year}`,'trophy')}${metric('Fantasy points',value(s?.pts),`Record: ${record(s)}`)}${metric('Recorded season trades',trades.length,'Partial archive','trades')}${metric('Players in saved roster',value(D.rosters.meta.total_rostered),`${year} · all teams`,'players')}</div><div class="story-links"><a href="${url('standings.html')}">${icon('standings')}<span><strong>Follow the season</strong><small>Records, points & saved matchups</small></span>${icon('arrow')}</a><a href="${url('trade.html')}">${icon('trades')}<span><strong>Revisit the deals</strong><small>Players, picks & trade partners</small></span>${icon('arrow')}</a><a href="${url('drafts.html')}">${icon('drafts')}<span><strong>Open the draft room</strong><small>Draft selections & future picks</small></span>${icon('arrow')}</a></div><div class="grid-main"><div class="stack">${panel('League standings',`${year} · head-to-head points`,standingsTable(rows,true),link('Full standings',url('standings.html')))}${panel('The long game',esc(teamName(selectedOwner)),trendChart([selectedOwner],true),link('Team history',url('team.html',{owner:selectedOwner,tab:'history'})))}</div><div class="stack overview-side">${panel('Recorded trades',`${year} · known dates first`,tradeFeed(trades),link('View all',url('trade.html')))}${panel('Your saved roster','Roster status, not inferred acquisitions',rosterBreakdown(selectedOwner),link('Roster',teamUrl(selectedOwner)))}${panel('Recorded champion',year,`<div class="panel-body"><h3>${esc(champ||'Not recorded')}</h3><p class="status-line">${champ?'Champion as recorded in the saved season data.':'No champion is inferred from the standings.'}</p></div>`)}</div></div>`;}
function pagination(total){const pages=Math.max(1,Math.ceil(total/pageSize));page=Math.max(1,Math.min(page,pages));return `<div class="pagination"><span>${total?`${(page-1)*pageSize+1}–${Math.min(page*pageSize,total)} of ${fmt(total)}`:'0 results'}</span><div class="buttons"><button class="btn" data-page-step="-1" ${page<=1?'disabled':''}>Previous</button><span>${page} / ${pages}</span><button class="btn" data-page-step="1" ${page>=pages?'disabled':''}>Next</button></div></div>`;}
function tableControls({team=false}={}){return `<div class="toolbar"><div class="search-field">${icon('search')}<input id="player-filter" type="search" placeholder="Find a player…" aria-label="Filter players" value="${esc(param('q'))}"></div>${team?'':`<select id="owner-filter" aria-label="Filter by team">${ownerOptions(param('filterOwner'),true)}</select>`}<select id="status-filter" aria-label="Filter roster status"><option value="">All statuses</option>${['ACTIVE','RESERVE','IR','MINORS','UNROSTERED'].map(s=>`<option value="${s}" ${param('status')===s?'selected':''}>${s==='UNROSTERED'?'Not in saved roster':s}</option>`).join('')}</select><select id="position-filter" aria-label="Filter position"><option value="">All positions</option>${['PG','SG','SF','PF','C','G','F','UTIL'].map(p=>`<option ${param('position')===p?'selected':''}>${p}</option>`).join('')}</select><button class="btn" data-reset>Reset</button></div>`;}
function playerTable(rows){tableRows=rows;const q=normal(param('q')),own=param('filterOwner'),status=param('status'),pos=param('position');let filtered=rows.filter(p=>normal(p.player_name).includes(q)&&(!own||p.owner_real_name===own)&&(!status||(p.roster_status||'UNROSTERED')===status)&&(!pos||String(p.position).split(/[\/,\s]+/).includes(pos)));filtered.sort((a,b)=>String(a[sortKey]??'').localeCompare(String(b[sortKey]??''),undefined,{numeric:true})*sortDirection);const pager=pagination(filtered.length);const th=(key,label)=>`<th scope="col" aria-sort="${sortKey===key?(sortDirection===1?'ascending':'descending'):'none'}"><button class="sort-button" data-sort="${key}">${label}<span>${sortKey===key?(sortDirection===1?'↑':'↓'):'↕'}</span></button></th>`;return `<div class="table-wrap"><table><thead><tr>${th('player_name','Player')}${th('position','Pos')}<th scope="col">Saved team</th>${th('roster_status','Status')}<th scope="col">Acquired</th><th scope="col">Explore</th></tr></thead><tbody>${filtered.slice((page-1)*pageSize,page*pageSize).map(p=>`<tr><td>${playerLink(p.player_id,p.player_name)}</td><td><span class="pill">${esc(p.position||'—')}</span></td><td>${p.owner_real_name?teamCell(p.owner_real_name):'<span class="muted">Not in saved roster</span>'}</td><td><span class="pill">${esc(p.roster_status||'—')}</span></td><td class="muted">Unknown</td><td><div class="row-actions"><button class="text-link" data-player="${esc(p.player_id)}">Details</button><a class="journey-link" href="${playerUrl(p.player_id)}">Profile</a><button class="expand-button" data-expand-player="${esc(p.player_id)}" aria-expanded="false" aria-label="Expand ${esc(p.player_name)} history">${icon('chevron')}</button></div></td></tr><tr class="expanded-player-row" hidden data-expanded-row="${esc(p.player_id)}"><td colspan="6">${playerTimeline(p.player_id)}</td></tr>`).join('')}</tbody></table></div>${filtered.length?'':empty('No players match these filters')}${pager}`;}
function allPlayers(){return Object.values(playerMap).map(p=>({...p,...(rosterMap[p.player_id]||{})}));}
function players(){return `${heading('Player explorer','Search saved rosters and recorded league history.',`<span class="pill">${Object.keys(playerMap).length} players</span>`)}${coverageNote()}${tableControls()}<section class="panel" id="player-results">${playerTable(allPlayers())}</section>`;}
function teams(){const requested=param('owner');if(!ownerMap[requested])return `${heading(view==='roster'?'Saved rosters':'The teams',`${owners.length} franchises. Choose a team to explore.`)}${coverageNote()}<div class="team-grid">${owners.map(o=>{const s=ownerStanding(o.real_name);return `<a class="team-card" href="${teamUrl(o.real_name)}">${badge(o.real_name,true)}<h2>${esc(teamName(o.real_name))}</h2><p class="muted small">${esc(operatorName(o.real_name))}</p><div class="card-stats"><span><strong>${s?'#'+s.rank:'—'}</strong>Recorded rank</span><span><strong>${record(s)}</strong>Record</span><span><strong>${rosterAvailable()?D.rosters.by_owner[o.real_name]?.length||0:'—'}</strong>Saved players</span></div></a>`;}).join('')}</div>`;
 const o=ownerMap[requested],s=ownerStanding(requested),tab=param('tab','roster'),roster=D.rosters.by_owner[requested]||[],trades=sortedTrades().filter(t=>t.parties.includes(requested)&&t.year===year);let content;
 if(tab==='performance'){const other=param('compare');content=`<div class="grid-two">${panel('Recorded results',`${year} · head-to-head points`,standingsTable(s?[s]:[]))}${panel('Season standings','Partial seasons remain labeled',trendChart([requested,...(ownerMap[other]&&other!==requested?[other]:[])]))}</div><div class="section-space">${panel('Compare teams','Recorded season results',`<div class="panel-body"><label class="select-label">Compare against<select id="compare-owner"><option value="">Choose a team</option>${owners.filter(x=>x.real_name!==requested).map(x=>`<option value="${esc(x.real_name)}" ${other===x.real_name?'selected':''}>${esc(teamName(x.real_name))}</option>`).join('')}</select></label></div>${ownerMap[other]?standingsTable(seasonRows().filter(r=>[requested,other].includes(r.owner_real_name))):''}`)}</div>`;}
 else if(tab==='trades')content=panel('Recorded trades',`${year} · ${trades.length} saved deals`,tradeList(trades),link('Open explorer',url('trade.html',{filterOwner:requested})));
 else if(tab==='history')content=`<div class="grid-two">${panel('The long game','Recorded standings rank',trendChart([requested]))}${panel('Franchise history','Team-name continuity; operators may change',`<div class="panel-body">${o.owner_id==='baden'?'<p class="notice">Spencer Vlandis → Brendan Kelley → Sam Baden. Exact transition dates remain unresolved; franchise results are not all attributed to the current operator.</p>':''}<ol class="timeline">${o.history.slice().reverse().map(h=>{const r=ownerStanding(requested,h.season);return `<li><time>${h.season}</time><strong>${esc(h.team_name)}</strong><p>Recorded #${r?.rank||'—'} · ${record(r)} · ${value(r?.pts)} fantasy points</p></li>`;}).join('')}</ol></div>`)}</div>`;
 else content=rosterAvailable()?`${tableControls({team:true})}<section class="panel" id="player-results">${playerTable(roster)}</section><div class="grid-two section-space">${panel('Saved roster composition','Acquisition method unavailable',rosterBreakdown(requested))}${panel('Recorded standings','Season history',trendChart([requested],true))}</div>`:empty('Roster unavailable','This season has trade records but no saved roster.');
 return `<div class="team-heading">${badge(requested,true)}<div><div class="eyebrow muted">TEAM CLUBHOUSE</div><h1>${esc(teamName(requested))}</h1><p>${esc(operatorName(requested))} · Franchise view</p><a class="text-link" href="${url('team_rankings.html',{rankTeam:requested})}">Roster rankings →</a></div><select class="team-switch" id="team-switch" aria-label="Switch team">${ownerOptions(requested)}</select></div>${coverageNote()}<div class="metric-row">${metric(`${year} standing`,s?'#'+s.rank:'—',`of ${owners.length} teams`,'trophy')}${metric('Fantasy points',value(s?.pts),`Record: ${record(s)}`)}${metric('Saved roster',rosterAvailable()?roster.length:'—',`${year} snapshot`,'players')}${metric('Recorded trades',trades.length,'Partial season archive','trades')}</div><nav class="tabs" aria-label="Team sections">${['roster','performance','trades','history'].map(t=>`<a class="tab ${tab===t?'active':''}" href="${url('team.html',{owner:requested,tab:t})}" ${tab===t?'aria-current="page"':''}>${({roster:'Roster',performance:'Performance & compare',trades:'Trades',history:'Franchise history'})[t]}</a>`).join('')}</nav>${content}`;
}
function playerTimeline(id){const p=playerMap[id];if(!p)return '';return `<p class="status-line">Saved observations do not establish continuous ownership. Acquisition and exit dates are unknown unless independently recorded.</p><ol class="timeline">${p.observations.slice().reverse().map(s=>`<li><time>${s.season} · saved roster</time><strong><a href="${url('team.html',{owner:s.owner,season:s.season})}">${esc(s.team_name)}</a></strong><p>${esc(s.operator_name||operatorName(s.owner,s.season))} · observed ownership, ${s.date?date(s.date):'date unavailable'}</p></li>`).join('')}${p.reported_moves.map(s=>`<li><time>${esc(s.season)} · ${s.date?date(s.date):'date unknown'}</time><strong>${esc(s.from||'Unknown sender')} → ${esc(s.to||'Unknown recipient')}</strong><p>Reported trade · derived legacy history, not a certified ownership interval</p></li>`).join('')}</ol>${!p.observations.length&&!p.reported_moves.length?empty('No ownership observations','This player appears in the saved trade log; a full history is unavailable.'):''}`;}
function playerProfile(id,full=false){const p=playerMap[id];if(!p)return empty('Player not found','Return to Players and choose a saved player.');const r=rosterMap[id],stats=p.stats[year];const related=sortedTrades().filter(t=>t.assets.some(a=>a.player_id===id));const profile=`<div class="profile-top"><span class="player-avatar big">${esc(initials(p.player_name))}</span><div><h2>${esc(p.player_name)}</h2><p>${esc(r?.position||p.position||'Position unavailable')}</p></div></div><div class="mini-title"><span class="muted small">Saved ownership · ${year}</span></div>${r?teamCell(r.owner_real_name):`<p class="muted small">${rosterAvailable()?'Not present in this saved roster.':'No roster available for this season.'}</p>`}<div class="profile-stats"><div><strong>${p.observations.length}</strong><span>Roster observations</span></div><div><strong>${related.length}</strong><span>Recorded trades</span></div><div><strong>Unknown</strong><span>Acquired</span></div></div>${stats?`<div class="production-stats">${[['gp','GP'],['ppg','PPG'],['rpg','RPG'],['apg','APG'],['fpts_pg','Est. FP/G']].map(([k,l])=>`<span><small>${l}</small><b>${value(stats[k])}</b></span>`).join('')}</div><p class="status-line">${year} NBA per-game stats${year==='2025-26'?' · partial':''}. Estimated fantasy points use saved scoring and rounded inputs; not credited lineup totals.</p>`:'<p class="status-line">No saved NBA stats for this season.</p>'}${p.identity_status!=='fantrax'?'<p class="coverage-note">Legacy player identity; Fantrax ID unresolved.</p>':''}`;
 if(!full)return `${profile}<div class="mini-title"><h3>Recorded history</h3><a class="journey-link" href="${playerUrl(id)}">Full profile</a></div>${playerTimeline(id)}`;
 return `${heading(esc(p.player_name),'Saved observations and recorded trades.',link('All players',url('players.html')))}${coverageNote()}<div class="player-layout section-space">${panel('Recorded ownership','Observed snapshots; incomplete transaction history',`<div class="panel-body">${playerTimeline(id)}</div>`)}<div class="stack">${panel('Player snapshot',year,`<div class="panel-body">${profile}</div>`)}${panel('Related trades','Across saved seasons',tradeFeed(related,8))}</div></div>`;
}
function filteredTrades(){const q=normal(param('q')),owner=param('filterOwner'),partner=param('partner'),type=param('type');return sortedTrades().filter(t=>t.year===year&&(!owner||t.parties.includes(owner))&&(!partner||t.parties.includes(partner))&&(!type||t.trade_type_label===type)&&normal(t.assets.map(a=>a.label).join(' ')+' '+t.parties.join(' ')).includes(q));}
function tradeList(events){const pager=pagination(events.length);return `<div class="table-wrap"><table><thead><tr><th scope="col">Recorded date</th><th scope="col">Parties</th><th scope="col">Assets</th><th scope="col">Type</th><th scope="col">Explore</th></tr></thead><tbody>${events.slice((page-1)*pageSize,page*pageSize).map(t=>`<tr><td>${t.date_iso?date(t.date_iso):'Date unknown'}<small class="block muted">${t.year}</small></td><td>${t.parties.map(p=>`<a class="text-link" href="${teamUrl(p)}">${esc(tradeActor(t,p).split(' ').slice(-1)[0])}</a>`).join(' / ')||'Unknown'}</td><td class="asset-cell">${esc(t.assets.map(a=>a.label).join(' · '))}${t.route_status==='recipient_unresolved'?'<small class="block muted">Recipients unresolved</small>':''}</td><td><span class="pill">${esc(t.trade_type_label)}</span></td><td><a class="text-link" href="${url('trade.html',{trade:t.event_id})}" data-trade="${esc(t.event_id)}">Details</a></td></tr>`).join('')}</tbody></table></div>${events.length?'':empty('No matching recorded trades')}${pager}`;}
function tradeDetail(id){const t=D.trades.trade_events.find(t=>t.event_id===id);if(!t)return empty('Trade not found','The requested event is absent from this saved archive.');return `<div class="profile-top"><span class="player-avatar big">${icon('trades')}</span><div><h2>${t.parties.map(p=>esc(tradeActor(t,p).split(' ').slice(-1)[0])).join(' ↔ ')||'Unresolved parties'}</h2><p>${t.year} · ${t.date_iso?date(t.date_iso):'Date unknown'} · ${esc(t.trade_type_label)}</p></div></div><p class="notice">${t.route_status==='recipient_unresolved'?'Mixed prefixes or multiple parties: recipients cannot be safely reconstructed. Original records are preserved below.':'Two-party directions reconstructed from saved sender prefixes; full transaction coverage is not certified.'}</p><div class="trade-sides">${t.parties.map(p=>`<section class="trade-side"><h3><a href="${url('team.html',{owner:p,season:t.year})}">${esc(teamName(p,t.year))}</a></h3><p class="muted small">Recorded operator: ${esc(tradeActor(t,p))}</p><div class="mini-title">Recorded outgoing assets</div><ul class="asset-list">${t.assets.filter(a=>a.sender===p).map(a=>`<li>${a.player_id?playerLink(a.player_id,playerMap[a.player_id]?.player_name||a.label,false):esc(a.label)} <span class="pill">${a.type}</span></li>`).join('')||'<li>None recorded</li>'}</ul><div class="mini-title">Received</div><ul class="asset-list">${t.route_status==='recipient_unresolved'?'<li>Unresolved</li>':t.assets.filter(a=>a.recipient===p).map(a=>`<li>${esc(a.label)}</li>`).join('')||'<li>None recorded</li>'}</ul></section>`).join('')}</div><details class="raw-details"><summary>Original source entries & limitations</summary><p>Saved YK trade log, entry ${t.source_index}. ${t.fantrax_confirmed?'The archive marks this record Fantrax-confirmed; this port has not reverified the transaction.':'No independent verification flag.'} Picks are preserved as descriptions; names from inferred pick outcomes are not treated as traded players.</p>${['give','get'].map(side=>`<h3>${side==='give'?'Give column':'Get column'}</h3><ul>${t.assets.filter(a=>a.side===side).map(a=>`<li>${esc(a.raw)}</li>`).join('')}</ul>`).join('')}</details>`;}
function tradeSummary(){const ts=filteredTrades();return `<div class="metric-row">${metric('Matching records',ts.length,`${year} saved log`,'trades')}${metric('Player assets',ts.reduce((n,t)=>n+t.assets.filter(a=>a.type==='player').length,0),'Recorded asset mentions','players')}${metric('Pick assets',ts.reduce((n,t)=>n+t.assets.filter(a=>a.type==='pick').length,0),'Outcomes not inferred','drafts')}${metric('Unresolved routes',ts.filter(t=>t.route_status!=='two_party_record').length,'Shown without guessed recipients')}</div>`;}
function tradePartners(){const focus=param('filterOwner')||selectedOwner,counts=owners.filter(o=>o.real_name!==focus).map(o=>({name:o.real_name,count:D.trades.trade_events.filter(t=>t.year===year&&t.parties.includes(focus)&&t.parties.includes(o.real_name)).length})).filter(x=>x.count).sort((a,b)=>b.count-a.count);return panel('Recorded trade partners',`${year} · ${esc(teamName(focus))}`,`<div class="panel-body"><div class="bar-chart">${counts.map(x=>`<a class="bar-line" href="${url('trade.html',{filterOwner:focus,partner:x.name})}"><span>${esc(x.name.split(' ').slice(-1)[0])}</span><div class="bar-track"><div class="bar-fill" style="width:${x.count/Math.max(...counts.map(c=>c.count),1)*100}%"></div></div><strong>${x.count}</strong></a>`).join('')||'<p class="muted">No partners recorded for this season.</p>'}</div><p class="status-line">Counts shared events, not verified asset flow in multi-party trades.</p></div>`);}
function workbookTrades(){const q=normal(param('q')),rows=D.context.recent_trades.filter(t=>normal(t.give.join(' ')+' '+t.get.join(' ')+' '+t.date).includes(q));return `<div class="panel-body"><p class="status-line">${D.context.recent_trades.length} dated summer 2026 trades from the supplied workbook. These lead into 2026–27 and are independent of the saved-roster season. Recorded asset prefixes identify the sending side. Trade execution and protected-pick outcomes have not been independently verified.</p></div><div class="report-card-grid workbook-trades">${rows.map(t=>`<article class="trade-side"><div class="activity-top"><strong>${date(t.date)}</strong><span class="pill">Workbook record</span></div><div class="trade-sides">${[['Sending side A',t.give],['Sending side B',t.get]].map(([label,assets])=>`<div><h3>${label}</h3><ul class="asset-list">${assets.map(a=>`<li>${esc(a)}</li>`).join('')}</ul></div>`).join('')}</div><p class="status-line">YK Dynasty Basketball.xlsx · ${esc(t.sheet)} · ${esc(t.source_range)}</p></article>`).join('')}</div>${rows.length?'':empty('No workbook trades match')}`;}
function trades(){const mode=param('tradeView','archive'),tabs=`<nav class="tabs" aria-label="Trade record sources"><a class="tab ${mode==='archive'?'active':''}" href="${url('trade.html')}">Saved archive</a><a class="tab ${mode==='updates'?'active':''}" href="${url('trade.html',{tradeView:'updates'})}">Summer 2026 updates</a></nav>`;if(mode==='updates')return `${heading('Trade explorer','Newly supplied summer trades.')}${tabs}<div class="toolbar"><div class="search-field">${icon('search')}<input id="context-trade-filter" type="search" aria-label="Search summer trades" placeholder="Find a player, pick or sender…" value="${esc(param('q'))}"></div><button class="btn" data-reset>Reset</button></div><section class="panel" id="context-trades">${workbookTrades()}</section>`;return `${heading('Trade explorer','Revisit the deals, players and picks in the saved league record.')}${coverageNote()}${tabs}<div id="trade-summary">${tradeSummary()}</div><div class="toolbar"><div class="search-field">${icon('search')}<input id="trade-filter" type="search" aria-label="Search trades" placeholder="Find a player, pick or owner…" value="${esc(param('q'))}"></div><select id="trade-owner" aria-label="Filter trades by team">${ownerOptions(param('filterOwner'),true)}</select><select id="trade-partner" aria-label="Filter trade partner">${ownerOptions(param('partner'),true)}</select><select id="trade-type" aria-label="Filter trade type"><option value="">All asset types</option>${['Players','Picks','Players + picks'].map(x=>`<option ${param('type')===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn" data-reset>Reset</button></div><section class="panel" id="trade-results">${tradeList(filteredTrades())}</section><div class="section-space" id="trade-partners">${tradePartners()}</div>`;}
function scoringInfo(){const s=D.scoring[year];return s?`<div class="panel-body"><p>Head-to-head points standings use recorded wins, losses and ties. Points scored are shown separately; sorting by points does not redefine the official rank.</p><p class="formula">PTS + REB + 2×AST + 4×STL + 4×BLK + 2×FGM − FGA + FTM − FTA + 3PM − 2×TO</p><p class="status-line">Verified against the saved ${year} league settings and the target ${D.target.season} settings. Player estimates from rounded per-game stats are separate from official team points.</p></div>`:empty('Scoring evidence unavailable for this season','Later-season settings are not backfilled as historical fact.');}
function matchups(){const source=D.matchups[year],rows=source?.matchups||[],periods=[...new Set(rows.map(r=>r.period))].sort((a,b)=>a-b),selected=Number(param('period',periods[periods.length-1]||0)),period=periods.includes(selected)?selected:periods[periods.length-1];if(!rows.length)return empty('No saved matchups','Weekly history is incomplete.');return `<div class="panel-body"><label class="select-label">Saved scoring period<select id="matchup-period" aria-label="Scoring period">${periods.map(p=>`<option value="${p}" ${p===period?'selected':''}>Period ${p}</option>`).join('')}</select></label><p class="status-line">Only periods ${periods.join(', ')} are saved. This is not a complete season race.</p></div><div class="table-wrap"><table><thead><tr><th>Away</th><th>Points</th><th>Home</th><th>Points</th></tr></thead><tbody>${rows.filter(r=>r.period===period).map(r=>`<tr><td>${esc(r.away_team)}</td><td>${value(r.away_score)}</td><td>${esc(r.home_team)}</td><td>${value(r.home_score)}</td></tr>`).join('')}</tbody></table></div>`;}
function standings(){const champ=D.standings.champions[year];return `${heading('League standings','Head-to-head records and fantasy points from the saved season.')}${coverageNote()}${panel('Recorded standings',`${year} · saved Fantrax order · through ${date(D.standings.as_of[year])}`,standingsTable())}<div class="grid-two section-space">${panel('Saved matchups','Limited scoring-period coverage',matchups())}${panel('League scoring','Basketball points rules',scoringInfo())}</div><div class="section-space">${panel('Recorded champion',year,`<div class="panel-body"><h3>${esc(champ||'Not recorded')}</h3><p class="status-line">A champion is never inferred from first place in regular-season standings.</p></div>`)}</div>`;}
const draftOwnerOptions=()=>ownerOptions(param('filterOwner'),true)+`<option value="Jared Sands" ${param('filterOwner')==='Jared Sands'?'selected':''}>The Unction · Jared Sands</option>`;
function recordedOwner(name,label){return name&&ownerMap[name]?`<a class="text-link" href="${teamUrl(name)}">${esc(label||name)}</a><small class="block muted">Franchise history: ${esc(name)}</small>`:`<strong>${esc(name||label||'Unresolved')}</strong>${!name?'<small class="block muted">Picker annotation unresolved</small>':''}`;}
function draftTable(){
 const drafts=D.context.drafts, chosen=Number(param('draftYear',String(year).slice(0,4))), source=drafts.find(d=>d.draft_year===chosen)||drafts.at(-1),owner=param('filterOwner'),q=normal(param('q'));
 const rows=source.picks.slice().sort((a,b)=>a.round-b.round||a.slot-b.slot).filter(p=>(!owner||p.owner===owner)&&normal(p.picker_label+' '+(p.owner||'')+' '+p.selected_player+' '+p.raw).includes(q));
 return `<div class="panel-body"><label class="select-label">Summer draft<select id="draft-year" aria-label="Summer draft year">${drafts.slice().reverse().map(d=>`<option value="${d.draft_year}" ${d===source?'selected':''}>${d.draft_year} → ${d.season}</option>`).join('')}</select></label><p class="status-line">Selections recorded in YK Dynasty Basketball.xlsx · ${esc(source.sheet)}. First two rounds, including the listed extra first-round slot in 2023. Summer ${source.draft_year} leads into ${source.season}; it is independent of the saved-roster season above.</p><p class="status-line">Multi-owner annotations remain unresolved. These selections do not establish current ownership or resolve the legacy pick ledger. Compensatory rounds are not fully reconciled.</p></div><div class="table-wrap"><table><thead><tr><th>Round</th><th>Slot</th><th>Recorded picker</th><th>Selected player</th><th>Source</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${p.round}</td><td>${p.slot}</td><td class="asset-cell">${recordedOwner(p.owner,p.picker_label)}</td><td class="asset-cell">${p.player_id?playerLink(p.player_id,p.selected_player,false):esc(p.selected_player)}<details class="record-note"><summary>Record details</summary><p>${esc(p.raw)}</p></details></td><td>${esc(p.source_cell)}<small class="block muted">Workbook record</small></td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('No draft selections match')}<div class="panel-body"><p class="status-line">${source.picks.length} recorded selections in this draft. Archived Fantrax draft responses still contain order slots only.</p></div>`;
}
function picksTable(){const years=[...new Set(D.picks.holdings.map(p=>p.draft_year))].sort(),selected=Number(param('pickYear',years[0])),pickYear=years.includes(selected)?selected:years[0],owner=param('filterOwner'),q=normal(param('q'));const rows=D.picks.holdings.filter(p=>p.draft_year===pickYear&&(!owner||p.owner===owner)&&normal(p.label+' '+(p.owner||'')).includes(q));return `<div class="panel-body"><label class="select-label">Draft year<select id="pick-year" aria-label="Future draft year">${years.map(y=>`<option ${y===pickYear?'selected':''}>${y}</option>`).join('')}</select></label><p class="status-line">Updated from the supplied YK Dynasty Basketball workbook on ${D.context.imported_at}. Workbook capture date unknown. Holdings are independent of the saved-roster season above. Swaps and conditions are retained, not adjudicated.</p>${(D.context.pick_conditions[String(pickYear)]||[]).map(c=>`<p class="pick-condition">${esc(c)}</p>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Recorded holder</th><th>Pick / condition</th><th>Source cell</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${recordedOwner(p.owner,p.holder_label)}</td><td class="asset-cell">${esc(p.label)}</td><td>${esc(p.source_cell)}<small class="block muted">${esc(p.sheet)} · unverified</small></td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('No listed holdings match','An empty list is not proof that a team owns no picks.')}`;}
function pickOutcomes(){const owner=param('filterOwner'),q=normal(param('q')),rows=D.picks.ledger.filter(p=>(!owner||p.reported_owner===owner||p.original_owner===owner)&&normal(p.pick_id+' '+(p.reported_owner||'')+' '+(p.original_owner||'')).includes(q));return `<div class="panel-body"><p>The legacy ledger labels some slots “completed” or “projected,” but contains no selected-player evidence. The new workbook supplies draft selections separately, but the original-pick identity and protection chain have not been reconciled. All ${D.picks.ledger.length} legacy outcomes remain unresolved here.</p></div><div class="table-wrap"><table><thead><tr><th>Draft year</th><th>Round</th><th>Original franchise</th><th>Reported holder</th><th>Outcome</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${p.draft_year}</td><td>${p.round}</td><td>${esc(p.original_owner||'Unresolved')}</td><td>${esc(p.reported_owner||'Unresolved')}</td><td>Unresolved${p.is_swap?' · swap':''}</td></tr>`).join('')}</tbody></table></div>`;}
function drafts(){const tab=param('tab',location.pathname.endsWith('/picks.html')?'holdings':'order');return `${heading('The draft room','Recorded selections, future holdings and the picks still to be resolved.')}<div class="art-banner draft-art"><div><span class="eyebrow">THE NEXT CHAPTER</span><h2>Build for what comes next.</h2><p>2021–2026 draft records · Future picks through 2033</p></div></div><nav class="tabs" aria-label="Draft views">${[['order','Draft results'],['holdings','Future picks'],['outcomes','Pick outcomes']].map(([k,l])=>`<a class="tab ${tab===k?'active':''}" href="${url('drafts.html',{tab:k,filterOwner:param('filterOwner'),q:param('q'),draftYear:param('draftYear'),pickYear:param('pickYear')})}">${l}</a>`).join('')}</nav><div class="toolbar"><div class="search-field">${icon('search')}<input id="draft-filter" type="search" aria-label="Search draft records" placeholder="Find a team or pick…" value="${esc(param('q'))}"></div><select id="draft-owner" aria-label="Filter draft records by team">${draftOwnerOptions()}</select><button class="btn" data-reset>Reset</button></div><section class="panel" id="draft-results">${tab==='holdings'?picksTable():tab==='outcomes'?pickOutcomes():draftTable()}</section>`;}
function verification(){const t=D.target;return `<div class="panel-body"><p><strong>${esc(t.name)} · ${esc(t.season)}</strong> · verified ${date(t.checked_at)}.</p><p>${esc(t.scoring_type.replaceAll('_',' ').toLowerCase())} · ${esc(t.sport)} · ${t.team_count} teams · ${t.player_count} rostered players at verification.</p><p>League scoring dates: ${date(t.start)} – ${date(t.end)}. Public roster rules: ${t.roster_rules.maxTotalActivePlayers} active, ${t.roster_rules.maxTotalReservePlayers} reserve, ${t.roster_rules.maxTotalPlayers} main roster slots. IR/minors players are present beyond these main slots; full eligibility constraints remain unverified.</p><div class="notice"><strong>Remaining verification gaps</strong><ul>${t.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><details class="raw-details"><summary>Target team identity checks</summary><div class="table-wrap"><table><thead><tr><th>Target team</th><th>Recorded owner</th><th>Evidence</th></tr></thead><tbody>${t.teams.map(x=>`<tr><td>${esc(x.team_name)}</td><td>${esc(x.mapped_owner||'Unresolved')}</td><td>${x.identity_status==='documented_year_vii'?'Year VII report':'Saved-name match; operator not verified'}</td></tr>`).join('')}</tbody></table></div></details><p class="status-line">The validated 2026–27 public roster is active. Franchise links use saved team aliases and supplied Year VII ownership evidence; authenticated operator verification remains open.</p></div>`;}
function contextUpdates(){return panel('League updates','Supplied documents · imported '+D.context.imported_at,`<div class="context-updates">${D.context.notes.map(n=>`<article><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p><details class="record-note"><summary>Source</summary><p>${esc(n.source)}</p></details></article>`).join('')}</div>`,'','section-space');}
function leagueHistory(){const focus=ownerMap[param('historyFocus')]?param('historyFocus'):selectedOwner;return `${heading('League history','The record we have, and the gaps it leaves.')}${coverageNote()}<div class="history-art"><img src="assets/yk-history-collage.png" alt="YK Dynasty basketball collage with league lettering and team pennants" loading="lazy"></div>${contextUpdates()}<div class="grid-two">${panel('Season standings','Recorded ranks; 2025–26 is partial',`<div class="panel-body"><label class="select-label">Focus team<select id="history-focus" aria-label="Focus history team">${ownerOptions(focus)}</select></label></div>${trendChart([focus])}`)}${panel('Recorded champions','Saved season data',`<div class="panel-body"><ol class="timeline">${Object.entries(D.standings.champions).reverse().map(([s,c])=>`<li><time>${s}</time><strong>${esc(c||'Champion not recorded')}</strong><a class="text-link" href="${url('standings.html',{season:s})}">View saved standings</a></li>`).join('')}</ol></div>`)}</div><div class="section-space">${panel('Target league verification',`${esc(D.target.league_id)} · current roster and saved seasons`,verification())}</div><div class="section-space">${panel('Coverage & provenance','Evidence is not a completeness certificate',`<div class="panel-body"><ul class="coverage-list"><li>Rosters: 2022–23 through 2025–26 have unknown original capture dates; 2026–27 public roster captured October 21, 2026.</li><li>Trades: 138 saved records across 2020–21 through 2025–26. Dates and multi-party recipients are sometimes missing.</li><li>Player history: roster observations and reported trades. No inferred startup acquisition or continuous tenure.</li><li>Standings: normalized from labeled Fantrax columns. ${D.standings.reconciliation.length} points-scored discrepancies in legacy seasons.json were corrected; original files remain unchanged.</li><li>Matchups: two saved periods per available season; no complete weekly race.</li><li>Drafts: 123 workbook selections across summers 2021–2026. Archived Fantrax responses still have order slots only. Original-pick outcomes and compensatory rounds remain unreconciled.</li><li>Franchise identity: Vlandis/Kelley/Baden share a slot; exact historical operator transitions remain unresolved. The Berke franchise is operated by Jared Sands in 2026–27, documented in Year VII; historical records retain their original operator.</li></ul><p class="status-line">Source checksums are recorded with the normalized bundle. Public files contain allowlisted fields only.</p><div class="buttons">${link('Saved player stats',url('stats.html'))}${link('Historical trade reports',url('grades.html'))}</div></div>`)}</div>`;}
function statsPage(){const rows=Object.values(playerMap).filter(p=>p.stats[year]&&normal(p.player_name).includes(normal(param('q'))));return `${heading('Saved player stats','NBA production from archived per-game data.')}${coverageNote()}<div class="toolbar"><div class="search-field">${icon('search')}<input id="stats-filter" type="search" aria-label="Filter saved stats" value="${esc(param('q'))}" placeholder="Find a player…"></div></div><section class="panel" id="stats-results">${statsTable(rows)}</section>`;}
function statsTable(rows){const pager=pagination(rows.length);return `<div class="table-wrap"><table><thead><tr><th>Player</th><th>GP</th><th>PPG</th><th>RPG</th><th>APG</th><th>Estimated FP/G</th></tr></thead><tbody>${rows.slice((page-1)*pageSize,page*pageSize).map(p=>`<tr><td>${playerLink(p.player_id,p.player_name)}</td>${['gp','ppg','rpg','apg','fpts_pg'].map(k=>`<td>${value(p.stats[year][k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${pager}<p class="status-line panel-body">Saved ${year} NBA data${year==='2025-26'?' · partial season':''}. Estimates use rounded inputs and are not official credited lineup totals.</p>`;}
function reports(){return `${heading('Historical trade reports','Legacy calculations retained as dated evidence, separate from the trade ledger.')}${coverageNote()}<div class="notice">These archived grades and values are not recalculated or certified by this port. They contain incomplete player matching, inferred pick outcomes and differing trade counts. Use the trade explorer for source records.</div><nav class="tabs" aria-label="Historical reports">${[['grades','Grades'],['trade-cards','Cards'],['trade-leaderboard','Leaderboard'],['trade-value-over-time','Value over time']].map(([f,t])=>`<a class="tab ${location.pathname.endsWith('/'+f+'.html')?'active':''}" href="${url(f+'.html')}">${t}</a>`).join('')}</nav><section class="panel" id="legacy-report">${empty('Loading archived report…','')}</section>`;}
let reportRequest=0;
async function loadReport(){
 const request=++reportRequest,chosenSeason=year,file=location.pathname.split('/').pop(),mapping={'grades.html':'trade_grades','trade-cards.html':'trade_details','trade-leaderboard.html':'trade_leaderboard','trade-value-over-time.html':'trade_value_over_time'},name=mapping[file]||'trade_grades';
 try{
  const response=await fetch(`data/legacy/${name}.json`);if(!response.ok)throw Error('Unavailable');const d=await response.json();if(view!=='reports'||year!==chosenSeason||request!==reportRequest)return;
  const scope=param('reportScope','season'),all=scope==='all',rows=(d.trades||[]).filter(r=>all||r.season===year);
  const controls=`<div class="panel-body"><div class="buttons"><a class="btn" href="${url(file,{reportScope:'season'})}" ${!all?'aria-current="page"':''}>Selected season</a><a class="btn" href="${url(file,{reportScope:'all'})}" ${all?'aria-current="page"':''}>All saved reports</a></div><p class="status-line">${all?'All source seasons, including entries without a season.':year+' only; unassigned report entries are excluded.'} Generated ${esc(d.generated||'date unavailable')}. Original report indexes are not assumed to match the core trade ledger.</p></div>`;
  let body='';
  if(name==='trade_leaderboard'){
   const entries=all?d.overall:(d.seasons[year]||[]);
   body=`<div class="table-wrap"><table><thead><tr><th>Reported operator</th><th>Archived trade wins</th><th>Archived trade losses</th><th>Reported win %</th><th>Reported margin</th></tr></thead><tbody>${entries.map(r=>`<tr><td>${esc(r.owner)}</td><td>${value(r.wins)}</td><td>${value(r.losses)}</td><td>${r.win_pct==null?'—':(r.win_pct*100).toFixed(1)+'%'}</td><td>${value(r.total_margin)}</td></tr>`).join('')}</tbody></table></div><p class="status-line panel-body">Trade wins are judgments from the archived valuation model, not head-to-head league wins. Historical operators remain separate.</p>`;
  }else if(name==='trade_grades'){
   body=`<div class="table-wrap"><table><thead><tr><th>Source entry / season</th><th>Operator</th><th>Legacy grade</th><th>Confidence / basis</th><th>Received assets</th></tr></thead><tbody>${rows.flatMap(r=>['side_a','side_b'].filter(k=>r[k]).map(k=>{const side=r[k];return `<tr><td>${r.trade_index} · ${esc(r.season||'Season unknown')}</td><td>${esc(side.owner)}</td><td><span class="pill">${esc(side.combined_grade||side.grade||'INC')}</span></td><td class="asset-cell">${esc(side.confidence||r.grade_confidence||'Unknown')} · ${esc(side.grade_basis||'Original method')}</td><td class="asset-cell">${esc((side.received||[]).join(' · '))}</td></tr>`;})).join('')}</tbody></table></div>${d.meta?.methodology?`<details class="raw-details panel-body"><summary>Original grading method</summary><p>${esc(d.meta.methodology)}</p></details>`:''}`;
  }else if(name==='trade_details'){
   body=`<div class="report-card-grid panel-body">${rows.map(r=>`<article class="draft-compare-card"><div class="eyebrow">SOURCE CARD ${r.trade_id} · ${esc(r.season||'Season unknown')}</div><h3>${(r.sides||[]).map(x=>esc(x.owner)).join(' / ')}</h3><p class="status-line">${r.date?date(r.date):'Date unknown'} · archived valuation</p>${(r.sides||[]).map(side=>`<div class="production-side"><strong>${esc(side.owner)} · ${value(side.side_total)} reported value</strong><ul class="asset-list">${(side.assets||[]).map(a=>`<li>${esc(a.name)} · ${value(a.value)} <small>(${esc(a.asset_type)})</small></li>`).join('')}</ul></div>`).join('')}<p class="status-line">Pick-derived names and model results remain unverified.</p></article>`).join('')}</div>`;
  }else{
   body=`<div class="panel-body">${rows.map(r=>`<details class="raw-details"><summary>Source entry ${r.trade_id} · ${esc(r.season||'Season unknown')} · ${(r.receivers||[]).map(esc).join(' / ')}</summary><div class="table-wrap"><table><thead><tr><th>Evaluation period</th><th>Reported values (original units)</th><th>Model preference</th></tr></thead><tbody>${(r.eval_results||[]).map(e=>`<tr><td>${esc(e.label)}</td><td>${Object.entries(e.totals||{}).map(([o,v])=>esc(o)+': '+value(v)).join(' · ')}</td><td>${esc(e.winner||'Unresolved')}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}</div>`;
  }
  $('#legacy-report').innerHTML=controls+body+((name!=='trade_leaderboard'&&!rows.length)?empty('No report entries assigned to this season','Choose All saved reports to inspect entries with unknown seasons.'):'');
 }catch{if(request===reportRequest&&$('#legacy-report'))$('#legacy-report').innerHTML=empty('Archived report unavailable','The core dashboard remains available.');}
}
function render(){const main=$('#main-content');const renderers={overview,teams,roster:teams,players,player:()=>playerProfile(param('id'),true),trades,standings,drafts,history:leagueHistory,stats:statsPage,reports,rankings:()=>'',bubbles:()=>''};main.innerHTML=(renderers[view]||overview)()+footer();bindControls();if(view==='reports')loadReport();if(['rankings','bubbles'].includes(view))window.YKRankings.mount({D,year,owners,selectedOwner,teamName,teamCell,mode:view==='bubbles'?'bubbles':'explorer'});}
function refreshResults(){if(view==='players'||(view==='teams'&&param('tab','roster')==='roster')){if($('#player-results'))$('#player-results').innerHTML=playerTable(tableRows);}else if(view==='trades'){if(param('tradeView')==='updates'){$('#context-trades').innerHTML=workbookTrades();return;}$('#trade-results').innerHTML=tradeList(filteredTrades());$('#trade-summary').innerHTML=tradeSummary();$('#trade-partners').innerHTML=tradePartners();}else if(view==='drafts'){$('#draft-results').innerHTML=param('tab',location.pathname.endsWith('/picks.html')?'holdings':'order')==='holdings'?picksTable():param('tab')==='outcomes'?pickOutcomes():draftTable();bindPickYear();document.querySelectorAll('.tabs a').forEach(a=>{const u=new URL(a.href);for(const k of ['filterOwner','q','pickYear','draftYear']){if(param(k))u.searchParams.set(k,param(k));else u.searchParams.delete(k);}a.href=u.href;});}else if(view==='stats'){$('#stats-results').innerHTML=statsTable(Object.values(playerMap).filter(p=>p.stats[year]&&normal(p.player_name).includes(normal(param('q')))));}else render();}
function bindPickYear(){$('#draft-year')?.addEventListener('change',e=>{setParams({draftYear:e.target.value},true);refreshResults();});$('#pick-year')?.addEventListener('change',e=>{setParams({pickYear:e.target.value},true);refreshResults();});}
function bindControls(){const configs=[['player-filter','q'],['owner-filter','filterOwner'],['status-filter','status'],['position-filter','position'],['trade-filter','q'],['context-trade-filter','q'],['trade-owner','filterOwner'],['trade-partner','partner'],['trade-type','type'],['draft-filter','q'],['draft-owner','filterOwner'],['stats-filter','q']];configs.forEach(([id,key])=>{const el=$('#'+id);if(el)el.addEventListener(el.tagName==='INPUT'?'input':'change',e=>{page=1;setParams({[key]:e.target.value,page:null},el.tagName!=='INPUT');refreshResults();});});$('#team-switch')?.addEventListener('change',e=>{location.href=url('team.html',{owner:e.target.value,tab:param('tab','roster')});});$('#compare-owner')?.addEventListener('change',e=>{setParams({compare:e.target.value},true);render();});$('#matchup-period')?.addEventListener('change',e=>{setParams({period:e.target.value},true);render();});$('#history-focus')?.addEventListener('change',e=>{setParams({historyFocus:e.target.value},true);render();});bindPickYear();}
function showDialog(type,id,trigger,fromUrl=false){const dialog=$('#detail-dialog');dialogTrigger=trigger||document.activeElement;const title=type==='player'?'Player quick view':'Trade details';dialog.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="close-btn" aria-label="Close details" data-close>${icon('close')}</button></div><div class="modal-content">${type==='player'?playerProfile(id):tradeDetail(id)}</div>`;if(!dialog.open)dialog.showModal();if(!fromUrl)setParams({[type==='player'?'quickPlayer':'trade']:id},true);}
function restoreDialog(){const p=params();if(p.has('quickPlayer'))showDialog('player',p.get('quickPlayer'),null,true);else if(p.has('trade'))showDialog('trade',p.get('trade'),null,true);else if($('#detail-dialog').open)$('#detail-dialog').close();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-player],[data-trade],[data-close],[data-menu],[data-page-step],[data-sort],[data-reset],[data-select-owner],[data-expand-player]');if(el){if(el.hasAttribute('data-select-owner'))selectTeam(el.dataset.selectOwner);else if(el.hasAttribute('data-expand-player')){const row=el.closest('tr').nextElementSibling;row.hidden=!row.hidden;el.setAttribute('aria-expanded',String(!row.hidden));}else if(el.hasAttribute('data-player')){if(e.metaKey||e.ctrlKey||e.shiftKey)return;e.preventDefault();showDialog('player',el.dataset.player,el);}else if(el.hasAttribute('data-trade')){if(e.metaKey||e.ctrlKey||e.shiftKey)return;e.preventDefault();showDialog('trade',el.dataset.trade,el);}else if(el.hasAttribute('data-close'))closeDialog();else if(el.hasAttribute('data-menu')){document.body.classList.toggle('menu-open');$('.mobile-menu').setAttribute('aria-expanded',document.body.classList.contains('menu-open'));syncMenuAccessibility();if(document.body.classList.contains('menu-open'))$('.side-link.active')?.focus();else $('.mobile-menu')?.focus();}else if(el.hasAttribute('data-page-step')){page+=Number(el.dataset.pageStep);setParams({page},true);refreshResults();}else if(el.hasAttribute('data-sort')){sortDirection=sortKey===el.dataset.sort?-sortDirection:1;sortKey=el.dataset.sort;setParams({sort:sortKey,dir:sortDirection},true);refreshResults();}else if(el.hasAttribute('data-reset')){page=1;setParams({q:null,filterOwner:null,status:null,position:null,partner:null,type:null,page:null},true);render();}}if(!e.target.closest('.top-search'))closeSearch();if(!e.target.closest('.team-picker'))closeTeamPicker();});
function closeDialog(){setParams({quickPlayer:null,trade:null});$('#detail-dialog').close();if(dialogTrigger?.isConnected)dialogTrigger.focus();else $('#main-content').focus();}
$('#detail-dialog').addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#detail-dialog').open){e.preventDefault();$('#global-search')?.focus();}if(e.key==='Escape'){closeSearch();const picker=$('#selected-team-options');if(picker&&!picker.hidden)closeTeamPicker(true);else if(document.body.classList.contains('menu-open')){document.body.classList.remove('menu-open');$('.mobile-menu')?.setAttribute('aria-expanded','false');syncMenuAccessibility();$('.mobile-menu')?.focus();}}if(e.key==='ArrowDown'&&e.target.closest('#global-results')){e.preventDefault();const links=[...document.querySelectorAll('#global-results a')],index=links.indexOf(e.target.closest('a'));links[(index+1)%links.length]?.focus();}if(e.key==='ArrowUp'&&e.target.closest('#global-results')){e.preventDefault();const links=[...document.querySelectorAll('#global-results a')],index=links.indexOf(e.target.closest('a'));if(index===0)$('#global-search').focus();else links[index-1]?.focus();}});
function restoreState(){activateSeason(param('season',currentYear));page=Math.max(1,Number(param('page',1))||1);sortKey=param('sort','player_name');sortDirection=param('dir')==='-1'?-1:1;}
window.addEventListener('popstate',()=>{restoreState();shell();render();restoreDialog();});
async function init(){try{const r=await fetch('data/dashboard.json');if(!r.ok)throw Error('Saved league data unavailable');D=await r.json();if(D.schema_version!==1)throw Error('Unsupported snapshot version');owners=D.teams.owners;ownerMap=Object.fromEntries(owners.map(o=>[o.real_name,o]));playerMap=D.journeys.player_index;currentYear=D.default_season;
 // Compatibility with old YK owner keys without changing the selected-team preference.
 for(const key of ['owner','filterOwner','compare','partner']){const query=param(key);if(query&&!ownerMap[query]){const o=owners.find(o=>o.aliases.some(a=>normal(a)===normal(query)));if(o)setParams({[key]:o.real_name});}}
 let saved;try{saved=localStorage.getItem('yk_selected_owner');}catch{}selectedOwner=ownerMap[saved]?saved:owners.find(o=>o.owner_id==='zujewski')?.real_name||owners[0].real_name;restoreState();shell();render();restoreDialog();
 }catch(err){$('#app').innerHTML=`<div class="loading"><img src="assets/yk-husky.png" alt="YK"><h1>The clubhouse couldn’t load.</h1><p>${esc(err.message)}</p><button class="btn" onclick="location.reload()">Try again</button></div>`;console.error(err);}}
matchMedia('(max-width:700px)').addEventListener('change',syncMenuAccessibility);
init();
})();
